insert into public.test_questions (test_id, question, options, correct, explanation, topic, difficulty, sort_order) values
  ((select id from t), '2¹⁰ ning qiymatini toping.', array['512', '100', '2048', '1024'], 3, '2¹⁰ = 1024.', 'Daraja va ildiz', 1, 1),
  ((select id from t), '√0,49 = ?', array['0,07', '0,7', '0,49', '7'], 1, '0,7 · 0,7 = 0,49.', 'Daraja va ildiz', 1, 2),
  ((select id from t), '3⁻² = ?', array['1/9', '1/6', '−9', '−6'], 0, 'a⁻ⁿ = 1/aⁿ, 3⁻² = 1/9.', 'Daraja va ildiz', 2, 3),
  ((select id from t), '240 ning 25 foizi nechaga teng?', array['96', '60', '48', '24'], 1, '240 · 0,25 = 60.', 'Foizlar', 1, 4),
  ((select id from t), 'Narx 200 000 so‘m edi. Avval 10 % oshirildi, keyin 10 % kamaytirildi. Yangi narx?', array['200 000 so‘m', '180 000 so‘m', '202 000 so‘m', '198 000 so‘m'], 3, '200 000 · 1,1 = 220 000; 220 000 · 0,9 = 198 000.', 'Foizlar', 3, 5),
  ((select id from t), '5x + 3 = 2x + 18 tenglamani yeching.', array['3', '7', '15', '5'], 3, '3x = 15, x = 5.', 'Tenglamalar', 1, 6),
  ((select id from t), 'x² − 9 = 0 tenglamaning ildizlari?', array['9', '−3 va 3', '3', '−9 va 9'], 1, 'x² = 9, x = ±3.', 'Kvadrat tenglamalar', 1, 7),
  ((select id from t), 'x² + 4x + 4 = 0 tenglamaning ildizi?', array['−4', '−2', '2', '4'], 1, '(x + 2)² = 0, x = −2.', 'Kvadrat tenglamalar', 2, 8),
  ((select id from t), '2x² − 3x − 5 = 0 tenglamaning diskriminantini toping.', array['1', '49', '−31', '31'], 1, 'D = b² − 4ac = 9 + 40 = 49.', 'Kvadrat tenglamalar', 2, 9),
  ((select id from t), 'x + y = 10 va x − y = 4 sistemaning yechimi?', array['x = 3, y = 7', 'x = 6, y = 4', 'x = 7, y = 3', 'x = 5, y = 5'], 2, 'Qo‘shsak: 2x = 14, x = 7; y = 3.', 'Tenglamalar sistemasi', 2, 10),
  ((select id from t), '2x − 3 > 7 tengsizlikni yeching.', array['x < 5', 'x > 5', 'x > 2', 'x > 10'], 1, '2x > 10, x > 5.', 'Tengsizliklar', 1, 11),
  ((select id from t), 'log₃ 81 = ?', array['3', '4', '27', '9'], 1, '3⁴ = 81.', 'Logarifm', 1, 12),
  ((select id from t), 'lg 1000 = ?', array['10', '4', '100', '3'], 3, '10³ = 1000.', 'Logarifm', 1, 13),
  ((select id from t), 'log₂ 32 − log₂ 4 = ?', array['3', '8', '5', '28'], 0, 'log₂ 32 = 5, log₂ 4 = 2, 5 − 2 = 3.', 'Logarifm', 2, 14),
  ((select id from t), 'tg 45° = ?', array['1', '√3', '0', '1/2'], 0, null, 'Trigonometriya', 1, 15),
  ((select id from t), 'sin²α + cos²α = ?', array['tg α', '1', '0', '2'], 1, 'Asosiy trigonometrik ayniyat.', 'Trigonometriya', 1, 16),
  ((select id from t), 'Arifmetik progressiyada a₁ = 5, d = 3. Dastlabki 10 ta hadning yig‘indisi?', array['150', '185', '320', '155'], 1, 'S₁₀ = (2·5 + 9·3) · 10 / 2 = 37 · 5 = 185.', 'Progressiyalar', 3, 17),
  ((select id from t), 'Geometrik progressiyada b₁ = 3, q = 2. Dastlabki 5 ta hadning yig‘indisi?', array['48', '45', '93', '96'], 2, 'S₅ = 3 · (2⁵ − 1) / (2 − 1) = 93.', 'Progressiyalar', 3, 18),
  ((select id from t), 'Asoslari 6 va 10, balandligi 5 bo‘lgan trapetsiyaning yuzi?', array['40', '60', '30', '80'], 0, 'S = (6 + 10) / 2 · 5 = 40.', 'Planimetriya', 2, 19),
  ((select id from t), 'Radiusi 7 ga teng aylananing uzunligi?', array['28π', '49π', '7π', '14π'], 3, 'C = 2πr = 14π.', 'Planimetriya', 1, 20),
  ((select id from t), 'Tomonlari 5, 12 va 13 bo‘lgan uchburchakning yuzi?', array['30', '65', '60', '78'], 0, '5² + 12² = 13² — to‘g‘ri burchakli; S = 5 · 12 / 2 = 30.', 'Planimetriya', 3, 21),
  ((select id from t), 'Oltiburchak ichki burchaklarining yig‘indisi?', array['360°', '540°', '720°', '1080°'], 2, '(n − 2) · 180° = 4 · 180° = 720°.', 'Planimetriya', 2, 22),
  ((select id from t), 'Radiusi 3 ga teng sharning hajmi?', array['27π', '108π', '36π', '12π'], 2, 'V = 4/3 · π · 27 = 36π.', 'Stereometriya', 2, 23),
  ((select id from t), 'O‘yin soqqasi tashlandi. Juft son tushish ehtimoli?', array['1/3', '2/3', '1/2', '1/6'], 2, '6 tadan 3 tasi juft: 2, 4, 6.', 'Ehtimollik', 1, 24),
  ((select id from t), '5 kishidan 2 kishini necha usulda tanlash mumkin?', array['25', '10', '20', '7'], 1, 'C(5, 2) = 5 · 4 / 2 = 10.', 'Kombinatorika', 2, 25),
  ((select id from t), 'y = 3x² − 4x + 1 funksiyaning hosilasi?', array['6x² − 4', '6x + 1', '6x − 4', '3x − 4'], 2, null, 'Hosila', 2, 26),
  ((select id from t), '∫₀² 2x dx = ?', array['1', '8', '2', '4'], 3, 'x² ni 0 dan 2 gacha: 4 − 0 = 4.', 'Integral', 3, 27);
insert into public.test_questions (test_id, question, options, correct, explanation, topic, difficulty, sort_order) values
  ((select id from t), '72 km/soat necha m/s ga teng?', array['7,2 m/s', '36 m/s', '72 m/s', '20 m/s'], 3, '72 000 m / 3600 s = 20 m/s.', 'Kinematika', 1, 1),
  ((select id from t), 'Jism tinch holatdan 2 m/s² tezlanish bilan harakatlandi. 5 s dan keyingi tezligi?', array['25 m/s', '2,5 m/s', '7 m/s', '10 m/s'], 3, 'v = at = 2 · 5 = 10 m/s.', 'Kinematika', 1, 2),
  ((select id from t), 'Jism tinch holatdan 2 m/s² tezlanish bilan 5 s harakatlandi. Bosib o‘tgan yo‘li?', array['20 m', '50 m', '25 m', '10 m'], 2, 's = at²/2 = 2 · 25 / 2 = 25 m.', 'Kinematika', 2, 3),
  ((select id from t), 'Erkin tushayotgan jismning 2 s dan keyingi tezligi (g = 10 m/s²)?', array['40 m/s', '10 m/s', '20 m/s', '5 m/s'], 2, 'v = gt = 20 m/s.', 'Kinematika', 1, 4),
  ((select id from t), 'Massasi 5 kg bo‘lgan jismning og‘irligi (g = 10 m/s²)?', array['50 N', '500 N', '0,5 N', '5 N'], 0, 'P = mg = 50 N.', 'Dinamika', 1, 5),
  ((select id from t), 'Bikrligi 200 N/m bo‘lgan prujina 5 sm cho‘zildi. Elastiklik kuchi?', array['1000 N', '10 N', '4 N', '40 N'], 1, 'F = kx = 200 · 0,05 = 10 N.', 'Dinamika', 2, 6),
  ((select id from t), '200 N kuch 0,5 m² yuzaga tik ta’sir qilmoqda. Bosim?', array['200 Pa', '100 Pa', '400 Pa', '1000 Pa'], 2, 'p = F / S = 200 / 0,5 = 400 Pa.', 'Bosim', 1, 7),
  ((select id from t), 'Suvning 10 m chuqurlikdagi bosimi (ρ = 1000 kg/m³, g = 10 m/s², atmosfera bosimisiz)?', array['1000 kPa', '1 kPa', '10 kPa', '100 kPa'], 3, 'p = ρgh = 1000 · 10 · 10 = 100 000 Pa.', 'Bosim', 2, 8),
  ((select id from t), 'Hajmi 0,002 m³ jism suvga to‘liq botirildi. Arximed kuchi (g = 10 m/s²)?', array['20 N', '2 N', '0,2 N', '200 N'], 0, 'F = ρgV = 1000 · 10 · 0,002 = 20 N.', 'Bosim', 2, 9),
  ((select id from t), '50 N kuch jismni kuch yo‘nalishida 4 m ga ko‘chirdi. Bajarilgan ish?', array['12,5 J', '46 J', '54 J', '200 J'], 3, 'A = F · s = 200 J.', 'Ish va quvvat', 1, 10),
  ((select id from t), 'Dvigatel 60 s da 1200 J ish bajardi. Quvvati?', array['1260 W', '2 W', '72 000 W', '20 W'], 3, 'P = A / t = 1200 / 60 = 20 W.', 'Ish va quvvat', 1, 11),
  ((select id from t), 'Massasi 3 kg, tezligi 4 m/s bo‘lgan jismning impulsi?', array['7 kg·m/s', '0,75 kg·m/s', '24 kg·m/s', '12 kg·m/s'], 3, 'p = mv = 12 kg·m/s.', 'Impuls', 1, 12),
  ((select id from t), '4 Om va 6 Om li rezistorlar ketma-ket ulangan. Umumiy qarshilik?', array['10 Om', '2 Om', '2,4 Om', '24 Om'], 0, 'Ketma-ket: R = R₁ + R₂.', 'Elektr toki', 1, 13),
  ((select id from t), '6 Om va 3 Om li rezistorlar parallel ulangan. Umumiy qarshilik?', array['18 Om', '4,5 Om', '9 Om', '2 Om'], 3, 'R = R₁R₂ / (R₁ + R₂) = 18 / 9 = 2 Om.', 'Elektr toki', 2, 14),
  ((select id from t), 'Kuchlanish 220 V, tok kuchi 5 A. Elektr quvvati?', array['44 W', '215 W', '1100 W', '225 W'], 2, 'P = UI = 1100 W.', 'Elektr toki', 1, 15),
  ((select id from t), '1 kW·soat necha joulga teng?', array['3600 J', '3,6·10³ J', '3,6·10⁶ J', '1000 J'], 2, '1000 W · 3600 s = 3 600 000 J.', 'Birliklar', 2, 16),
  ((select id from t), '2 kg suvni 10 °C ga isitish uchun qancha issiqlik kerak (c = 4200 J/(kg·°C))?', array['84 kJ', '840 kJ', '8,4 kJ', '42 kJ'], 0, 'Q = cmΔt = 4200 · 2 · 10 = 84 000 J.', 'Issiqlik', 2, 17),
  ((select id from t), 'Bosim o‘zgarmas bo‘lgan jarayon qanday nomlanadi?', array['Izotermik', 'Izoxorik', 'Adiabatik', 'Izobarik'], 3, null, 'Molekulyar fizika', 1, 18),
  ((select id from t), 'Tebranish chastotasi 50 Hz. Tebranish davri?', array['2 s', '0,5 s', '50 s', '0,02 s'], 3, 'T = 1 / ν = 1 / 50 = 0,02 s.', 'Tebranish va to‘lqinlar', 1, 19),
  ((select id from t), 'Tovush tezligi 340 m/s, chastotasi 170 Hz. To‘lqin uzunligi?', array['57 800 m', '2 m', '0,5 m', '510 m'], 1, 'λ = v / ν = 340 / 170 = 2 m.', 'Tebranish va to‘lqinlar', 2, 20),
  ((select id from t), 'Yassi ko‘zgudagi tasvir qanday bo‘ladi?', array['Mavhum, to‘g‘ri, buyum bilan teng kattalikda', 'Mavhum, teskari, kichraygan', 'Haqiqiy, to‘g‘ri, kattalashgan', 'Haqiqiy, teskari, kichraygan'], 0, null, 'Optika', 1, 21),
  ((select id from t), 'Fokus masofasi 0,5 m bo‘lgan yig‘uvchi linzaning optik kuchi?', array['2 dptr', '5 dptr', '−2 dptr', '0,5 dptr'], 0, 'D = 1 / F = 1 / 0,5 = 2 dptr.', 'Optika', 2, 22),
