insert into public.test_questions (test_id, question, options, correct, explanation, topic, difficulty, sort_order) values
  ((select id from t), 'He ___ like coffee.', array['don''t', 'doesn''t', 'isn''t', 'not'], 1, 'He/she/it + does not.', 'Present Simple', 1, 1),
  ((select id from t), 'We ___ to London last year.', array['go', 'went', 'goes', 'have gone'], 1, '«Last year» → Past Simple.', 'Past Simple', 1, 2),
  ((select id from t), 'She has ___ finished her homework.', array['already', 'yet', 'last', 'ago'], 0, '«Already» goes with Present Perfect in positive sentences.', 'Present Perfect', 2, 3),
  ((select id from t), 'While I ___ dinner, the phone rang.', array['have cooked', 'am cooking', 'was cooking', 'cooked'], 2, 'A longer action interrupted → Past Continuous.', 'Past Continuous', 2, 4),
  ((select id from t), 'By next year, they ___ the new bridge.', array['have built', 'built', 'will build', 'will have built'], 3, '«By + future time» → Future Perfect.', 'Future Perfect', 3, 5),
  ((select id from t), 'If I ___ rich, I would travel around the world.', array['were', 'had been', 'will be', 'am'], 0, 'Second conditional: if + Past Simple (were), would + verb.', 'Conditionals', 2, 6),
  ((select id from t), 'He asked me where I ___.', array['lived', 'am living', 'do live', 'live'], 0, 'Reported question: tenses move back, no inversion.', 'Reported speech', 3, 7),
